INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24001, 102301, 401, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 2, "アヤネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24002, 102301, 402, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 0.0, 10046, 0.0, 2.21, "2030/12/17 14:59:59", 1, "アヤネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24003, 102301, 403, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 2, "アヤネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24004, 192201, 701, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 0.0, 10046, 0.0, 1.99, "2030/12/17 14:59:59", 2, "アサヒ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24005, 192201, 702, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 0.0, 10046, 0.0, 2.21, "2030/12/17 14:59:59", 1, "アサヒ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24006, 192201, 703, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 0.0, 10046, 0.0, 3.33, "2030/12/17 14:59:59", 2, "アサヒ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24007, 192301, 801, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 2, "部員３", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24008, 192301, 802, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 0.0, 10046, 0.0, 2.68, "2030/12/17 14:59:59", 1, "部員３", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24009, 192301, 803, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 2, "部員３", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24010, 192501, 501, "やった！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 1, "", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24011, 192501, 502, "勝ったよ！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 1, "", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24012, 192501, 503, "いい調子！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 1, "", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24013, 113501, 111, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 0.0, 10046, 0.0, 5.33, "2030/12/17 14:59:59", 6, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24014, 113501, 112, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 0.0, 10046, 0.0, 6.85, "2030/12/17 14:59:59", 1, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24015, 113501, 113, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 0.0, 10046, 0.0, 3.0, "2030/12/17 14:59:59", 1, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24016, 192401, 611, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 0.0, 10046, 0.0, 6.11, "2030/12/17 14:59:59", 1, "ダイチ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24017, 192401, 612, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 0.0, 10046, 0.0, 6.75, "2030/12/17 14:59:59", 1, "ダイチ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24018, 192401, 613, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 2, "ダイチ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24019, 113401, 211, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 0.0, 10046, 0.0, 4.52, "2030/12/17 14:59:59", 2, "ハツネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24020, 113401, 212, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 0.0, 10046, 0.0, 3.89, "2030/12/17 14:59:59", 2, "ハツネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24021, 113401, 213, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 0.0, 10046, 0.0, 13.49, "2030/12/17 14:59:59", 1, "ハツネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24022, 106501, 311, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 0.0, 10046, 0.0, 3.17, "2030/12/17 14:59:59", 1, "カヤ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24023, 106501, 312, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 0.0, 10046, 0.0, 4.42, "2030/12/17 14:59:59", 1, "カヤ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24024, 106501, 313, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 0.0, 10046, 0.0, 2.89, "2030/12/17 14:59:59", 6, "カヤ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 3, 24025, 102301, 421, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 0.0, 10046, 0.0, 3.71, "2030/12/17 14:59:59", 4, "アヤネ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24026, 192201, 721, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 0.0, 10046, 0.0, 5.1, "2030/12/17 14:59:59", 2, "アサヒ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 3, 24027, 192301, 821, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 0.0, 10046, 0.0, 4.34, "2030/12/17 14:59:59", 1, "部員３", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24028, 192501, 521, "いい勝負だったよ\nまたやろうね", 0.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 1, "", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24029, 113501, 101, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", -360.0, 10046, 0.0, 5.62, "2030/12/17 14:59:59", 1, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24030, 113501, 102, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", -360.0, 10046, 0.0, 9.58, "2030/12/17 14:59:59", 1, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24031, 113501, 103, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", -360.0, 10046, 0.0, 0.0, "2030/12/17 14:59:59", 2, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 1, 24032, 113501, 104, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", -360.0, 10046, 0.0, 9.13, "2030/12/17 14:59:59", 2, "ミサト", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", 2, 24033, 113501, 105, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", -360.0, 10046, 0.0, 8.27, "2030/12/17 14:59:59", 1, "ミサト", 24);
